export function validateCT_AdjPoint2D(value: unknown, path = 'CT_AdjPoint2D'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (v['x'] === undefined) {
    issues.push(issue(path + '.x', 'missing-required', 'required attribute is absent'));
  } else {
    issues.push(...validateST_AdjCoordinate(v['x'], path + '.x'));
  }
  if (v['y'] === undefined) {
    issues.push(issue(path + '.y', 'missing-required', 'required attribute is absent'));
  } else {
    issues.push(...validateST_AdjCoordinate(v['y'], path + '.y'));
  }
  return issues;
}

export function validateCT_AdjustHandleList(value: unknown, path = 'CT_AdjustHandleList'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (!Array.isArray(v['content'])) {
  } else {
    for (let i = 0; i < (v['content'] as readonly unknown[]).length; i += 1) {
      if ((v['content'] as readonly unknown[])[i] && typeof (v['content'] as readonly unknown[])[i] === 'object') {
        const item = (v['content'] as readonly unknown[])[i] as { kind?: unknown; value?: unknown };
        if (item.kind !== '$raw') {
          if (item.kind === 'ahXY') issues.push(...validateCT_XYAdjustHandle(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'ahPolar') issues.push(...validateCT_PolarAdjustHandle(item.value, path + '.content[' + i + ']' + '.value'));
          if ('ahXY' !== item.kind && 'ahPolar' !== item.kind) issues.push(issue(path + '.content[' + i + ']', 'invalid-value', 'unknown choice alternative'));
        }
      }
    }
  }
  return issues;
}

