export function validateCT_AlphaInverseEffect(value: unknown, path = 'CT_AlphaInverseEffect'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (v['colorChoice'] === undefined) {
  } else {
    if (v['colorChoice'] && typeof v['colorChoice'] === 'object') {
      const item = v['colorChoice'] as { kind?: unknown; value?: unknown };
      if (item.kind !== '$raw') {
        if (item.kind === 'scrgbClr') issues.push(...validateCT_ScRgbColor(item.value, path + '.colorChoice' + '.value'));
        if (item.kind === 'srgbClr') issues.push(...validateCT_SRgbColor(item.value, path + '.colorChoice' + '.value'));
        if (item.kind === 'hslClr') issues.push(...validateCT_HslColor(item.value, path + '.colorChoice' + '.value'));
        if (item.kind === 'sysClr') issues.push(...validateCT_SystemColor(item.value, path + '.colorChoice' + '.value'));
        if (item.kind === 'schemeClr') issues.push(...validateCT_SchemeColor(item.value, path + '.colorChoice' + '.value'));
        if (item.kind === 'prstClr') issues.push(...validateCT_PresetColor(item.value, path + '.colorChoice' + '.value'));
        if ('scrgbClr' !== item.kind && 'srgbClr' !== item.kind && 'hslClr' !== item.kind && 'sysClr' !== item.kind && 'schemeClr' !== item.kind && 'prstClr' !== item.kind) issues.push(issue(path + '.colorChoice', 'invalid-value', 'unknown choice alternative'));
      }
    }
  }
  return issues;
}

